1	//! The language-neutral resolution engine (Task 2, PR-1).
2	//!
3	//! `resolve` / `resolve_path` walk the scope graph and consult a
4	//! [`ResolutionPolicy`](crate::name_resolution::types::ResolutionPolicy) at
5	//! every decision point. **No Rust-ism lives here** — the Rust rules (per-rib
6	//! order, module-boundary stop, glob accessibility, anchors, candidate
7	//! combination, the `visible()` predicate) all live in
8	//! [`crate::name_resolution::rust_policy`]. The engine is generic over
9	//! `&dyn ResolutionPolicy`.
10	//!
11	//! ## The cardinal invariant (spec §7)
12	//! **Resolve-or-fall-through, NEVER a wrong target.** A bare name that fails to
13	//! resolve returns `Unresolved`/`Ambiguous`/`Poisoned` — the engine never
14	//! silently picks a wrong outer same-name item. Every shadow/poison/visibility
15	//! decision is structured so the *worst* outcome is a missed (not a wrong) edge.
16	//!
17	//! ## Engine ⇄ policy seam
18	//! The engine asks the policy three structural questions during the walk:
19	//! - `edge_order()` — which `EdgeKindId`s to follow at a rib (Rust: just `Glob`;
20	//!   the lexical-parent step is the engine's structural ascent, gated below).
21	//! - `ascend_to_parent(scope_kind)` — **policy-gated** lexical ascent (the Rust
22	//!   module-boundary stop lives here). Defaulted on the trait for non-Rust
23	//!   policies that want an unconditional walk.
24	//! - `combine(candidates)` / `visible(binding, q, trav)` / `anchor(anchor, from)`.
25	
26	use crate::name_resolution::glob_stats::GlobExpandStats;
27	pub use crate::name_resolution::graph::ScopeGraph;
28	use crate::name_resolution::types::{
29	    Anchor, BindTarget, Binding, Candidate, CfgCond, CfgCtx, GlobEdgeVis, NamespaceId,
30	    PolicyQueryCtx, ResStatus, Resolution, ResolutionPolicy, ResolveQuery, ScopeId, SourceLoc,
31	    Target, TraversalCtx,
32	};
33	
34	// ── public entry points ───────────────────────────────────────────────────────
35	
36	/// Resolve a **bare** `(name, ns)` lookup from `q.from` at `q.at`.
37	///
38	/// Walks scopes inner→outer under the policy's per-rib order, with the policy's
39	/// lexical-ascent gate (the Rust module-boundary stop). Returns the per-candidate
40	/// [`Resolution`].
41	pub fn resolve(graph: &ScopeGraph, q: &ResolveQuery, policy: &dyn ResolutionPolicy) -> Resolution {
42	    let mut guard = CycleGuard::with_stats(None);
43	    resolve_bare(graph, q, policy, &mut guard)
44	}
45	
46	/// Resolve a multi-segment **path** anchored by `anchor` from `from`.
47	///
48	/// `anchor_ns` is the namespace used for the *prefix* (scope-bearing) segments
49	/// (Rust: Type/Module); `ns` is the namespace of the **final** segment. The
50	/// prefix segments are resolved as member lookups within each successive scope
51	/// (longest-prefix), the final segment within the final scope. No lexical
52	/// fall-out: an anchored path targets a specific scope chain and never silently
53	/// walks outward to a wrong same-name (§7).
54	#[allow(clippy::too_many_arguments)]
55	pub fn resolve_path(
56	    graph: &ScopeGraph,
57	    path: &crate::name_resolution::types::RawPath,
58	    ns: NamespaceId,
59	    anchor: &Anchor,
60	    from: ScopeId,
61	    anchor_ns: NamespaceId,
62	    at: &SourceLoc,
63	    policy: &dyn ResolutionPolicy,
64	) -> Resolution {
65	    let mut guard = CycleGuard::with_stats(None);
66	    resolve_path_guarded(
67	        graph, path, ns, anchor, from, anchor_ns, at, policy, &mut guard,
68	    )
69	}
