171	#[cfg(test)]
172	mod glob_guard_tests {
173	    use super::*;
174	
175	    #[test]
176	    fn enter_glob_tracks_depth_and_cycle_then_leaves() {
177	        let stats = crate::name_resolution::glob_stats::GlobExpandStats::default();
178	        let mut g = CycleGuard::with_stats(Some(&stats));
179	        assert_eq!(g.glob_depth(), 0);
180	        let entered = g.enter_glob(7);
181	        assert!(entered);
182	        assert_eq!(g.glob_depth(), 1);
183	        assert!(!g.enter_glob(7), "re-entering the same edge is a cycle");
184	        g.leave_glob(7);
185	        assert_eq!(g.glob_depth(), 0);
186	        assert!(g.enter_glob(7), "leaving clears the edge");
187	        g.leave_glob(7);
188	    }
189	}
