191	// ── the bare-name inner→outer walk ────────────────────────────────────────────
192	
193	fn resolve_bare(
194	    graph: &ScopeGraph,
195	    q: &ResolveQuery,
196	    policy: &dyn ResolutionPolicy,
197	    guard: &mut CycleGuard<'_>,
198	) -> Resolution {
199	    let mut cur = Some(q.from);
200	    while let Some(scope_id) = cur {
201	        // 1) Local explicit bindings for (name, ns) in-range + cfg-compatible.
202	        //    If this rib has ANY such binding, the rib is AUTHORITATIVE for the
203	        //    name: we resolve/visibility-filter/combine here and STOP. We never
204	        //    skip past a claimed name to an outer same-name (§7 decoy rule) —
205	        //    even an inaccessible match stops the walk (claim-then-fail-visibility
206	        //    ⇒ fall through, not a wrong outer target).
207	        //
208	        //    An explicit binding here ALSO SHADOWS a covering macro wildcard
209	        //    (§4.3b Reading B): the macro poisons "exactly like a deferred glob"
210	        //    (§3.4 step 2), and a deferred glob is shadowed by an explicit step-1
211	        //    binding — so the macro is checked at the GLOB TIER (step 2 below),
212	        //    AFTER this rib, not before it.
213	        let rib = self_rib_bindings(graph, scope_id, &q.name, q.ns, &q.at);
214	        if !rib.is_empty() {
215	            return resolve_rib(graph, &rib, q, policy, guard);
216	        }
217	
218	        // 2) Glob tier (reached only when step 1 found NO explicit binding for
219	        //    the name in this scope). A covering macro wildcard poisons here
220	        //    FIRST — exactly like a deferred glob (§4.3b / §7 poison-not-skip): a
221	        //    name-introducing item-position macro could emit `name`, and we
222	        //    cannot know its identity pre-expansion, so we poison (→ never reach
223	        //    an outer same-name) rather than fall through. It sits at the same
224	        //    tier as (and short-circuits ahead of) a same-scope non-deferred
225	        //    glob, mirroring the deferred-glob short-circuit in `glob_lookup`.
226	        if macro_wildcard_poisons(graph, scope_id, q.ns, &q.at) {
227	            return poisoned();
228	        }
229	        //    Else this scope's glob edges. A deferred glob poisons; otherwise
230	        //    union the visible (name, ns) members of each non-deferred glob
231	        //    target. Globs that yield NOTHING do not claim the name → continue.
232	        match glob_lookup(graph, scope_id, q, policy, guard) {
233	            GlobOutcome::Poison => return poisoned(),
234	            GlobOutcome::Hit(cands) => return policy.combine(cands),
235	            GlobOutcome::Empty => {}
236	        }
237	
238	        // 3) Else recurse to the lexical parent — policy-gated (Rust module
239	        //    boundary stop). If the policy says stop, fall through (Unresolved).
240	        let kind = match graph.scope(scope_id) {
241	            Some(s) => s.kind.clone(),
242	            None => break,
243	        };
244	        if !policy.ascend_to_parent(&kind) {
245	            break;
246	        }
247	        cur = graph.parent_of(scope_id);
248	    }
249	
250	    // Allow the policy to inject (prelude / ADL); empty for Rust Phase 1.
251	    let injected = policy.inject(q);
252	    if injected.is_empty() {
253	        unresolved()
254	    } else {
255	        policy.combine(injected)
256	    }
257	}
