259	/// Resolve the candidates claimed at a single rib (explicit bindings).
260	///
261	/// Pending targets are chased through the fixpoint (cycle-guarded). A still-
262	/// pending / cyclic import **poisons**. Visibility is enforced via the policy
263	/// hook; if every name-match fails visibility the result is `Unresolved` (fall
264	/// through) — we do NOT continue outward (the rib claimed the name).
265	fn resolve_rib(
266	    graph: &ScopeGraph,
267	    rib: &[usize],
268	    q: &ResolveQuery,
269	    policy: &dyn ResolutionPolicy,
270	    guard: &mut CycleGuard<'_>,
271	) -> Resolution {
272	    let mut candidates: Vec<Candidate> = Vec::new();
273	    for &bidx in rib {
274	        let b = &graph.bindings[bidx];
275	        // Visibility is checked against the binding as found at this rib.
276	        let trav = TraversalCtx {
277	            lookup_scope: Some(b.scope),
278	            via_glob: false,
279	            edge_kind: None,
280	        };
281	        if !policy.visible(b, q, &trav) {
282	            // Claimed the name but not visible → does not contribute a candidate
283	            // AND does not let us fall through to an outer item. We keep scanning
284	            // the rib (a sibling cfg-alternative may be visible) but never ascend.
285	            continue;
286	        }
287	        match &b.target {
288	            BindTarget::Resolved(t) => {
289	                candidates.push(Candidate {
290	                    target: t.clone(),
291	                    cond: cond_of(&b.cond),
292	                    provenance: Default::default(),
293	                });
294	            }
295	            BindTarget::Pending(path, anchor) => {
296	                // Chase the re-export chain from the BINDING'S OWN scope (the
297	                // re-export author's perspective — a `pub use` does NOT launder
298	                // privacy: the chased path must be visible at the re-export site).
299	                if !guard.enter(bidx) {
300	                    // Cycle: a still-pending import in a cycle poisons.
301	                    return poisoned();
302	                }
303	                // Prefix segments resolve in the policy's first scope-bearing
304	                // namespace (Rust: Type), NOT the final-segment ns of the query.
305	                let prefix_ns = policy.namespaces().first().copied().unwrap_or(b.ns);
306	                let sub = resolve_path_guarded(
307	                    graph, path, b.ns, anchor, b.scope, prefix_ns, &q.at, policy, guard,
308	                );
309	                guard.leave(bidx);
310	                match sub.status {
311	                    // A resolved (or legit set) chained target is folded in,
312	                    // re-conditioned by this binding's own cfg.
313	                    ResStatus::Resolved | ResStatus::ResolvedSet => {
314	                        for c in sub.candidates {
315	                            candidates.push(Candidate {
316	                                target: c.target,
317	                                cond: conjoin(&cond_of(&b.cond), &c.cond),
318	                                provenance: Default::default(),
319	                            });
320	                        }
321	                    }
322	                    ResStatus::Ambiguous => return ambiguous(sub.candidates),
323	                    // A STILL-PENDING import (its path is unresolvable, OR its
324	                    // target is not visible at the re-export site) ⇒ POISON, never
325	                    // fall through to an outer same-name (§4 / §7 poison-not-skip).
326	                    // `Poisoned` and `Unresolved` both mean "this import did not
327	                    // yield a concrete visible target" → poison.
328	                    ResStatus::Poisoned | ResStatus::Unresolved => return poisoned(),
329	                }
330	            }
331	        }
332	    }
333	    if candidates.is_empty() {
334	        // Claimed but nothing visible/resolvable → fall through (NOT outward).
335	        unresolved()
336	    } else {
337	        policy.combine(candidates)
338	    }
339	}
