341	// ── glob handling (non-deferred members known; deferred ⇒ poison) ─────────────
342	
343	enum GlobOutcome {
344	    /// A deferred/unexpanded glob in scope → poison.
345	    Poison,
346	    /// Glob(s) produced candidates.
347	    Hit(Vec<Candidate>),
348	    /// No glob produced anything (do not claim the name).
349	    Empty,
350	}
351	
352	fn glob_lookup(
353	    graph: &ScopeGraph,
354	    scope_id: ScopeId,
355	    q: &ResolveQuery,
356	    policy: &dyn ResolutionPolicy,
357	    guard: &mut CycleGuard<'_>,
358	) -> GlobOutcome {
359	    let glob_kinds = policy.edge_order();
360	    let mut candidates: Vec<Candidate> = Vec::new();
361	    let mut saw_glob = false;
362	    for (edge_idx, e) in graph.edges.iter().enumerate() {
363	        if e.from != scope_id || !glob_kinds.contains(&e.kind) {
364	            continue;
365	        }
366	        if e.vis_range
367	            .as_ref()
368	            .is_some_and(|span| !span_covers(span, &q.at))
369	        {
370	            continue;
371	        }
372	        if let BindTarget::Pending(path, _) = &e.to {
373	            if path.0.is_empty() {
374	                guard.stats().record_external();
375	                return GlobOutcome::Poison;
376	            }
377	        }
378	        let trav = TraversalCtx {
379	            lookup_scope: Some(scope_id),
380	            via_glob: true,
381	            edge_kind: Some(e.kind),
382	        };
383	        match policy.glob_edge_visible(e, q, &trav) {
384	            GlobEdgeVis::Hidden => continue,
385	            GlobEdgeVis::Unknown => {
386	                guard.stats().record_vis_unknown();
387	                return GlobOutcome::Poison;
388	            }
389	            GlobEdgeVis::Visible => {}
390	        }
391	        saw_glob = true;
392	        match &e.to {
393	            BindTarget::Pending(path, anchor) => {
394	                if guard.glob_depth() >= MAX_GLOB_DEPTH {
395	                    guard.stats().record_depth_exceeded();
396	                    return GlobOutcome::Poison;
397	                }
398	                let edge_outcome = guard.with_glob(edge_idx, |guard, entered| {
399	                    if !entered {
400	                        guard.stats().record_cycle();
401	                        return GlobOutcome::Poison;
402	                    }
403	
404	                    let prefix_ns = policy.namespaces().first().copied().unwrap_or(q.ns);
405	                    let target_res = resolve_path_guarded(
406	                        graph, path, prefix_ns, anchor, scope_id, prefix_ns, &q.at, policy, guard,
407	                    );
408	                    let (target_scope, target_cond) =
409	                        match (&target_res.status, target_res.candidates.as_slice()) {
410	                            (ResStatus::Resolved, [tc]) => match &tc.target {
411	                                Target::Scope(s) => (*s, tc.cond.clone()),
412	                                _ => {
413	                                    guard.stats().record_external();
414	                                    return GlobOutcome::Poison;
415	                                }
416	                            },
417	                            (ResStatus::Ambiguous | ResStatus::ResolvedSet, _) => {
418	                                guard.stats().record_multi_target();
419	                                return GlobOutcome::Poison;
420	                            }
421	                            (ResStatus::Resolved, _) => {
422	                                guard.stats().record_multi_target();
423	                                return GlobOutcome::Poison;
424	                            }
425	                            (ResStatus::Unresolved | ResStatus::Poisoned, _) => {
426	                                guard.stats().record_external();
427	                                return GlobOutcome::Poison;
428	                            }
429	                        };
430	
431	                    let (member_res, member_rib_present) =
432	                        scope_member_lookup_probed(graph, target_scope, q, policy, guard);
433	                    match member_res.status {
434	                        ResStatus::Resolved if member_res.candidates.len() == 1 => {
435	                            let mut member_candidates = member_res.candidates;
436	                            let mc = member_candidates.pop().expect("checked len == 1");
437	                            candidates.push(Candidate {
438	                                target: mc.target,
439	                                cond: conjoin(&cond_of(&e.cond), &conjoin(&target_cond, &mc.cond)),
440	                                provenance: Default::default(),
441	                            });
442	                            guard.stats().record_resolved(guard.glob_depth());
443	                            GlobOutcome::Empty
444	                        }
445	                        ResStatus::Resolved | ResStatus::ResolvedSet | ResStatus::Ambiguous => {
446	                            guard.stats().record_ambiguous();
447	                            GlobOutcome::Poison
448	                        }
449	                        ResStatus::Poisoned => GlobOutcome::Poison,
450	                        // `Unresolved` with NO rib claimed in the target → the target
451	                        // provably lacks the name → contribute nothing, continue to the
452	                        // next glob edge. But a rib that DID claim the name and was
453	                        // visibility-filtered to empty (a private or undecidable
454	                        // `pub(in)` member) ALSO surfaces as `Unresolved` *with*
455	                        // `rib_present` — we cannot prove the target lacks the name, so
456	                        // we must POISON, never fall through to a sibling glob's
457	                        // same-name (the §7 cardinal rule). Conservative: a *known*-
458	                        // private member could soundly continue; distinguishing it
459	                        // (a member-visibility tri-state, mirroring `glob_edge_visible`)
460	                        // is a deferred follow-on.
461	                        ResStatus::Unresolved if !member_rib_present => GlobOutcome::Empty,
462	                        ResStatus::Unresolved => {
463	                            guard.stats().record_ambiguous();
464	                            GlobOutcome::Poison
465	                        }
466	                    }
467	                });
468	                if matches!(edge_outcome, GlobOutcome::Poison) {
469	                    return GlobOutcome::Poison;
470	                }
471	            }
472	            BindTarget::Resolved(Target::Scope(target_scope)) => {
473	                // Union the visible (name, ns) members of the target scope.
474	                let members = glob_member_bindings(graph, *target_scope, &q.name, q.ns);
475	                for bidx in members {
476	                    let b = &graph.bindings[bidx];
477	                    let trav = TraversalCtx {
478	                        lookup_scope: Some(*target_scope),
479	                        via_glob: true,
480	                        edge_kind: Some(e.kind),
481	                    };
482	                    if !policy.visible(b, q, &trav) {
483	                        continue;
484	                    }
485	                    if let BindTarget::Resolved(t) = &b.target {
486	                        candidates.push(Candidate {
487	                            target: t.clone(),
488	                            cond: conjoin(&cond_of(&e.cond), &cond_of(&b.cond)),
489	                            provenance: Default::default(),
490	                        });
491	                    } else {
492	                        // A glob whose member is itself a still-Pending import:
493	                        // conservatively poison (we cannot know its identity).
494	                        return GlobOutcome::Poison;
495	                    }
496	                }
497	            }
498	            // A glob resolved to a non-scope target is malformed for Rust; treat
499	            // conservatively as no-contribution (the policy combination decides).
500	            BindTarget::Resolved(_) => {}
501	        }
502	    }
503	    if !saw_glob || candidates.is_empty() {
504	        GlobOutcome::Empty
505	    } else {
506	        GlobOutcome::Hit(candidates)
507	    }
508	}
