510	// ── path resolution (anchored member-lookup chain) ───────────────────────────
511	
512	#[allow(clippy::too_many_arguments)]
513	fn resolve_path_guarded(
514	    graph: &ScopeGraph,
515	    path: &crate::name_resolution::types::RawPath,
516	    ns: NamespaceId,
517	    anchor: &Anchor,
518	    from: ScopeId,
519	    anchor_ns: NamespaceId,
520	    at: &SourceLoc,
521	    policy: &dyn ResolutionPolicy,
522	    guard: &mut CycleGuard<'_>,
523	) -> Resolution {
524	    let segs = &path.0;
525	    if segs.is_empty() {
526	        return unresolved();
527	    }
528	    // Anchor the starting scope. `None` ⇒ conservative fall-through.
529	    let (mut scope, _start_ns) = match policy.anchor(anchor, from) {
530	        Some(x) => x,
531	        None => return unresolved(),
532	    };
533	
534	    // Walk the prefix segments as scope-bearing member lookups.
535	    for (i, seg) in segs.iter().enumerate() {
536	        let is_last = i + 1 == segs.len();
537	        let seg_ns = if is_last { ns } else { anchor_ns };
538	        // Build a query whose `from` is the ORIGINAL query origin so visibility
539	        // is judged from the caller's vantage (sibling-private decoys fall
540	        // through; pub facades resolve).
541	        let seg_q = ResolveQuery {
542	            name: seg.clone(),
543	            ns: seg_ns,
544	            from,
545	            at: at.clone(),
546	            cfg: CfgCtx::default(),
547	            ctx: PolicyQueryCtx::default(),
548	        };
549	        // Single-scope member lookup AND a "was a rib claimed here?" probe (so a
550	        // claimed-but-invisible local cannot be overridden by the crate fallback).
551	        let (res, rib_present) = scope_member_lookup_probed(graph, scope, &seg_q, policy, guard);
552	        // Leading-segment crate-root fallback (strictly last; P2/P3): a 2018+
553	        // extern-prelude root resolves to the owning crate's Root scope ONLY on a
554	        // TRUE no-rib miss — no rib was claimed for the segment (so a local item,
555	        // even a deliberately-invisible one, always shadows — P2) — AND the policy's
556	        // anchor/edition gate + the consuming crate's per-crate in-repo dependency
557	        // gate pass (P3). Poison/empty-glob `Unresolved` WITH a claimed rib does not
558	        // qualify. `from` (the query origin) is threaded so the policy can identify
559	        // the consuming crate.
560	        let res = if i == 0 && !rib_present && matches!(res.status, ResStatus::Unresolved) {
561	            match policy.extern_crate_root(graph, seg, anchor, from) {
562	                Some(root) => Resolution {
563	                    candidates: vec![Candidate {
564	                        target: Target::Scope(root),
565	                        cond: CfgCond::True,
566	                        provenance: Default::default(),
567	                    }],
568	                    status: ResStatus::Resolved,
569	                },
570	                None => res,
571	            }
572	        } else {
573	            res
574	        };
575	        if is_last {
576	            return res;
577	        }
578	        // Non-final: must resolve to exactly one scope-bearing target.
579	        match (&res.status, res.candidates.as_slice()) {
580	            (ResStatus::Resolved, [c]) => match scope_of_target(&c.target) {
581	                Some(s) => scope = s,
582	                None => return unresolved(), // not scope-bearing → fall through
583	            },
584	            // Poison propagates; anything non-singular falls through (never wrong).
585	            (ResStatus::Poisoned, _) => return poisoned(),
586	            _ => return unresolved(),
587	        }
588	    }
589	    unreachable!("path with >=1 segment returns inside the loop")
590	}
591	
592	/// Look up `(name, ns)` **within a single scope** (a path segment): explicit
593	/// bindings first (visibility-enforced, Pending chased), then this scope's
594	/// non-deferred globs. NO lexical fall-out (an anchored member lookup never
595	/// walks to a parent — that is what keeps a sibling-private decoy from reaching
596	/// an outer same-name).
597	///
598	/// ALSO reports whether an explicit rib binding for `(name, ns)` was CLAIMED in
599	/// this scope (regardless of visibility/outcome). The boolean lets
600	/// `resolve_path_guarded` distinguish a TRUE no-rib miss (where the crate-root
601	/// fallback may fire) from a claimed-but-invisible local rib (which surfaces as
602	/// `Unresolved` but must shadow the crate name — P2/BLOCKER 1). It does NOT change
603	/// the `Resolution` returned. (`resolve_path_guarded` is the only caller and needs
604	/// the flag, so there is no thin non-probed wrapper.)
605	fn scope_member_lookup_probed(
606	    graph: &ScopeGraph,
607	    scope: ScopeId,
608	    q: &ResolveQuery,
609	    policy: &dyn ResolutionPolicy,
610	    guard: &mut CycleGuard<'_>,
611	) -> (Resolution, bool) {
612	    // Explicit bindings in this scope for (name, ns), cfg-compatible. For path
613	    // member lookup we do NOT gate on vis_extents byte-range (a module member is
614	    // visible across the whole module to a path); visibility is the `visible()`
615	    // policy hook. An explicit member binding SHADOWS a covering macro wildcard
616	    // (the wildcard is glob-tier — §4.3b Reading B), so it is checked AFTER this
617	    // rib, not before.
618	    let rib: Vec<usize> = graph
619	        .bindings
620	        .iter()
621	        .enumerate()
622	        .filter(|(_, b)| b.scope == scope && b.name == q.name && b.ns == q.ns)
623	        .filter(|(_, b)| cfg_compatible(&b.cond))
624	        .map(|(i, _)| i)
625	        .collect();
626	    let rib_present = !rib.is_empty();
627	    if rib_present {
628	        return (resolve_rib(graph, &rib, q, policy, guard), true);
629	    }
630	    // Glob tier: a covering macro wildcard poisons here (exactly like a deferred
631	    // glob), reached only when the rib above found no explicit member binding.
632	    if macro_wildcard_poisons(graph, scope, q.ns, &q.at) {
633	        return (poisoned(), false);
634	    }
635	    // Else this scope's globs.
636	    let res = match glob_lookup(graph, scope, q, policy, guard) {
637	        GlobOutcome::Poison => poisoned(),
638	        GlobOutcome::Hit(cands) => policy.combine(cands),
639	        GlobOutcome::Empty => unresolved(),
640	    };
641	    (res, false)
642	}
643	
644	// ── binding selection helpers ─────────────────────────────────────────────────
645	
646	/// Indices of explicit `(name, ns)` bindings in `scope` whose `vis_extents`
647	/// cover `at.byte` and whose cfg is compatible with the query.
648	fn self_rib_bindings(
649	    graph: &ScopeGraph,
650	    scope: ScopeId,
651	    name: &str,
652	    ns: NamespaceId,
653	    at: &SourceLoc,
654	) -> Vec<usize> {
655	    graph
656	        .bindings
657	        .iter()
658	        .enumerate()
659	        .filter(|(_, b)| b.scope == scope && b.name == name && b.ns == ns)
660	        .filter(|(_, b)| vis_extent_covers(b, at))
661	        .filter(|(_, b)| cfg_compatible(&b.cond))
662	        .map(|(i, _)| i)
663	        .collect()
664	}
665	
666	/// Visible (name, ns) member indices in a glob target scope (no byte gate — a
667	/// glob brings a module's members regardless of the use site's byte).
668	fn glob_member_bindings(
669	    graph: &ScopeGraph,
670	    scope: ScopeId,
671	    name: &str,
672	    ns: NamespaceId,
673	) -> Vec<usize> {
674	    graph
675	        .bindings
676	        .iter()
677	        .enumerate()
678	        .filter(|(_, b)| b.scope == scope && b.name == name && b.ns == ns)
679	        .map(|(i, _)| i)
680	        .collect()
681	}
682	
683	/// Does any unexpanded-macro wildcard in `scope` for `ns` cover `at.byte`?
684	fn macro_wildcard_poisons(
685	    graph: &ScopeGraph,
686	    scope: ScopeId,
687	    ns: NamespaceId,
688	    at: &SourceLoc,
689	) -> bool {
690	    graph
691	        .macro_wildcards
692	        .iter()
693	        .any(|m| m.scope == scope && m.ns == ns && span_covers(&m.range, at))
694	}
695	
696	// ── small predicates / combinators ────────────────────────────────────────────
697	
698	fn vis_extent_covers(b: &Binding, at: &SourceLoc) -> bool {
699	    if b.vis_extents.is_empty() {
700	        // No recorded extent ⇒ treat as scope-wide (conservative: visible).
701	        return true;
702	    }
703	    b.vis_extents.iter().any(|s| span_covers(s, at))
704	}
705	
706	fn span_covers(s: &crate::name_resolution::types::Span, at: &SourceLoc) -> bool {
707	    // Half-open [lo, hi); same-file comparison (callers build same-file spans).
708	    s.lo.file == at.file && at.byte >= s.lo.byte && at.byte < s.hi.byte
709	}
710	
711	/// Whether a binding's cfg is compatible with the query's active cfg.
712	///
713	/// Phase 1 has no cfg *evaluation* (the `CfgCtx` is empty), so this is the
714	/// conservative `true` — every conditioned binding is *kept* (never silently
715	/// dropped); exclusivity between SIBLING candidates is handled later by the
716	/// policy's `combine` (cfg-exclusive ⇒ distinct worlds, not a conflict).
717	fn cfg_compatible(_cond: &Option<CfgCond>) -> bool {
718	    true
719	}
720	
721	fn cond_of(c: &Option<CfgCond>) -> CfgCond {
722	    c.clone().unwrap_or(CfgCond::True)
723	}
724	
725	/// Conjoin two cfg conditions (path accumulation), collapsing `True`.
726	fn conjoin(a: &CfgCond, b: &CfgCond) -> CfgCond {
727	    match (a, b) {
728	        (CfgCond::True, x) | (x, CfgCond::True) => x.clone(),
729	        _ => CfgCond::And(vec![a.clone(), b.clone()]),
730	    }
731	}
732	
733	fn scope_of_target(t: &Target) -> Option<ScopeId> {
734	    match t {
735	        Target::Scope(s) => Some(*s),
736	        Target::Item { owns: Some(s), .. } => Some(*s),
737	        _ => None,
738	    }
739	}
740	
741	// ── result constructors ───────────────────────────────────────────────────────
742	
743	fn unresolved() -> Resolution {
744	    Resolution {
745	        candidates: vec![],
746	        status: ResStatus::Unresolved,
747	    }
748	}
749	
750	fn poisoned() -> Resolution {
751	    Resolution {
752	        candidates: vec![],
753	        status: ResStatus::Poisoned,
754	    }
755	}
756	
757	fn ambiguous(candidates: Vec<Candidate>) -> Resolution {
758	    Resolution {
759	        candidates,
760	        status: ResStatus::Ambiguous,
761	    }
762	}
763

