1	//! The Rust [`ResolutionPolicy`] (Task 2, PR-1).
2	//!
3	//! Every Rust-specific resolution rule lives here — the engine
4	//! ([`crate::name_resolution::engine`]) is language-neutral and consults this
5	//! policy at each decision point. This struct supplies:
6	//!
7	//! - **Namespaces** `{Type, Value, Macro}` (Type is scope-bearing for prefixes).
8	//! - **Per-rib edge order** — Rust follows only `Glob` edges at a rib (the
9	//!   lexical-parent step is the engine's structural ascent, gated by
10	//!   `ascend_to_parent`); explicit binding ▷ this-scope glob ▷ lexical parent.
11	//! - **MODULE-BOUNDARY STOP** for bare names (`ascend_to_parent`): a bare name
12	//!   crosses `Block`/`Callable`/`Type` parents but **stops at the enclosing
13	//!   `Module`/`Root`** — Rust does not inherit unqualified names across a module
14	//!   boundary (§4 round6-B1). Only explicit `super::`/`crate::`/`self::` anchors
15	//!   + the extern-prelude reach module ancestors.
16	//! - **`visible()`** — `pub` / `pub(crate)` / `pub(super)` / `pub(in path)` /
17	//!   private accessibility, computed against the borrowed [`ScopeGraph`]'s
18	//!   ancestry. Un-enforced / unknown visibility **falls through** (never
19	//!   resolves a not-visible target — §7).
20	//! - **`combine()`** — single ⇒ `Resolved`; same-target dedup ⇒ `Resolved`;
21	//!   distinct-namespace set ⇒ `ResolvedSet`; cfg-exclusive worlds ⇒
22	//!   `ResolvedSet` (distinct worlds, never merged); conflicting compatible-cfg
23	//!   ⇒ `Ambiguous`.
24	//! - **Edition-aware anchors** (`crate`/`self`/`super`/bare/`::`, 2015 vs 2018).
25	//!
26	//! ## Recall-safety stance
27	//! Every hook is written so the *worst* outcome is a missed edge, never a wrong
28	//! one: an unknown visibility kind is **not visible**, an un-mappable anchor is
29	//! `None` (fall through), a non-provably-exclusive conflict is `Ambiguous`.
30	
31	use crate::name_resolution::graph::ScopeGraph;
32	use crate::name_resolution::types::{
33	    Anchor, AnchorKind, Binding, Candidate, Edge, EdgeKindId, GlobEdgeVis, NamespaceId, ResStatus,
34	    Resolution, ResolutionPolicy, ResolveQuery, ScopeId, ScopeKind, TraversalCtx, Vis, VisKindId,
35	};
36	
37	// ── Rust namespace registry (policy-owned discriminants) ──────────────────────
38	
39	/// Type namespace (modules, structs, enums, traits, type aliases).
40	pub const NS_TYPE: NamespaceId = 0;
41	/// Value namespace (fns, consts, statics, locals, tuple/unit ctors).
42	pub const NS_VALUE: NamespaceId = 1;
43	/// Macro namespace.
44	pub const NS_MACRO: NamespaceId = 2;
45	
46	// ── Rust visibility-kind registry ─────────────────────────────────────────────
47	
48	/// `pub` — visible everywhere the path reaches.
49	pub const VIS_PUB: VisKindId = 0;
50	/// `pub(crate)` — visible anywhere in the defining crate.
51	pub const VIS_PUB_CRATE: VisKindId = 1;
52	/// `pub(super)` — visible in the parent module's subtree.
53	pub const VIS_PUB_SUPER: VisKindId = 2;
54	/// `pub(in path)` — visible only inside the `restrict` scope's subtree.
55	pub const VIS_PUB_IN: VisKindId = 3;
56	/// private (the default) — visible in the defining module and its descendants.
57	pub const VIS_PRIV: VisKindId = 4;
58	
59	// ── Rust edge-kind registry ───────────────────────────────────────────────────
60	
61	/// A `use a::*` / `pub use a::*` glob edge.
62	pub const EK_GLOB: EdgeKindId = 1;
63	
64	// ── The policy struct ─────────────────────────────────────────────────────────
65	
66	/// The Rust resolution policy.
67	///
68	/// Borrows the [`ScopeGraph`] so `visible()` can compute module ancestry for
69	/// `pub(super)`/`pub(in)`/`pub(crate)`. `edition` selects 2015 vs 2018+ anchor
70	/// semantics (the only edition split Phase 1 needs).
71	pub struct RustPolicy<'g> {
72	    graph: &'g ScopeGraph,
73	    edition: u16,
74	}
75	
76	impl<'g> RustPolicy<'g> {
77	    /// Construct a policy over `graph` for the given `edition` (e.g. 2015/2018).
78	    pub fn new(graph: &'g ScopeGraph, edition: u16) -> Self {
79	        RustPolicy { graph, edition }
80	    }
81	
82	    fn is_2018_plus(&self) -> bool {
83	        self.edition >= 2018
84	    }
85	
86	    /// The enclosing `Module`/`Root` of `scope` (itself if it is one).
87	    fn enclosing_module(&self, scope: ScopeId) -> Option<ScopeId> {
88	        let mut cur = Some(scope);
89	        while let Some(id) = cur {
90	            let s = self.graph.scope(id)?;
91	            if matches!(s.kind, ScopeKind::Module | ScopeKind::Root) {
92	                return Some(id);
93	            }
94	            cur = s.parent;
95	        }
96	        None
97	    }
98	
99	    /// The crate `Root` ancestor of `scope`.
100	    ///
101	    /// Walks the parent chain and returns on the **first** (nearest) `Root` found;
102	    /// the `break` exits immediately, so the variable holds that Root, not a "last"
103	    /// or topmost one.
104	    fn crate_root(&self, scope: ScopeId) -> Option<ScopeId> {
105	        let mut cur = Some(scope);
106	        let mut root = None;
107	        while let Some(id) = cur {
108	            let s = self.graph.scope(id)?;
109	            if matches!(s.kind, ScopeKind::Root) {
110	                root = Some(id);
111	                break; // first Root found — exit immediately
112	            }
113	            cur = s.parent;
114	            if cur.is_none() {
115	                // Graph-without-Root safety net: no Root ancestor exists; treat
116	                // the topmost reachable scope as the crate root.
117	                root = Some(id);
118	            }
119	        }
120	        root
121	    }
122	
123	    /// Walk `n` module hops up from `scope`'s enclosing module.
124	    fn super_n(&self, scope: ScopeId, n: u32) -> Option<ScopeId> {
125	        let mut cur = self.enclosing_module(scope)?;
126	        for _ in 0..n {
127	            // `super` of the crate Root is undefined → fall through.
128	            let parent = self.graph.parent_of(cur)?;
129	            cur = self.enclosing_module(parent)?;
130	        }
131	        Some(cur)
132	    }
133	
134	    /// Is `desc` inside `ancestor`'s subtree (inclusive)?
135	    fn is_within(&self, desc: ScopeId, ancestor: ScopeId) -> bool {
136	        let mut cur = Some(desc);
137	        while let Some(id) = cur {
138	            if id == ancestor {
139	                return true;
140	            }
141	            cur = self.graph.parent_of(id);
142	        }
143	        false
144	    }
145	
146	    fn vis_reaches(&self, vis: &Vis, def_scope: ScopeId, from: ScopeId) -> Option<bool> {
147	        let def_module = match self.enclosing_module(def_scope) {
148	            Some(m) => m,
149	            None => return Some(false),
150	        };
151	        match vis.kind {
152	            VIS_PUB => Some(true),
153	            VIS_PUB_CRATE => Some(match (self.crate_root(def_scope), self.crate_root(from)) {
154	                (Some(a), Some(b)) => a == b,
155	                _ => false,
156	            }),
157	            VIS_PUB_SUPER => Some(match self.super_n(def_scope, 1) {
158	                Some(parent_mod) => self.is_within(from, parent_mod),
159	                None => false,
160	            }),
161	            VIS_PUB_IN => vis.restrict.map(|r| self.is_within(from, r)),
162	            VIS_PRIV => Some(self.is_within(from, def_module)),
163	            _ => Some(false),
164	        }
165	    }
166	}
167	
168	impl ResolutionPolicy for RustPolicy<'_> {
169	    fn namespaces(&self) -> Vec<NamespaceId> {
170	        // Scope-bearing namespaces for resolve_path prefixes: Type (modules,
171	        // type bodies). Value/Macro are final-segment-only.
172	        vec![NS_TYPE]
173	    }
174	
175	    fn edge_order(&self) -> Vec<EdgeKindId> {
176	        // Rust follows only Glob edges at a rib. (Lexical parent ascent is the
177	        // engine's structural step, gated by `ascend_to_parent` below.)
178	        vec![EK_GLOB]
179	    }
180	
181	    fn ascend_to_parent(&self, kind: &ScopeKind) -> bool {
182	        // THE MODULE-BOUNDARY STOP. A bare name crosses block/callable/type
183	        // lexical parents, but once we have looked in a Module/Root we STOP —
184	        // Rust does not inherit unqualified names from a parent module.
185	        matches!(
186	            kind,
187	            ScopeKind::Block | ScopeKind::Callable | ScopeKind::Type
188	        )
189	    }
190	
191	    fn combine(&self, candidates: Vec<Candidate>) -> Resolution {
192	        if candidates.is_empty() {
193	            return Resolution {
194	                candidates,
195	                status: ResStatus::Unresolved,
196	            };
197	        }
198	        // Dedup exact-duplicate candidates (same target + same cond) — e.g. two
199	        // glob paths to the SAME item (a re-export diamond) is a single Resolved,
200	        // not Ambiguous.
201	        let mut deduped: Vec<Candidate> = Vec::new();
202	        for c in candidates {
203	            if !deduped
204	                .iter()
205	                .any(|d| d.target == c.target && d.cond == c.cond)
206	            {
207	                deduped.push(c);
208	            }
209	        }
210	
211	        if deduped.len() == 1 {
212	            return Resolution {
213	                candidates: deduped,
214	                status: ResStatus::Resolved,
215	            };
216	        }
217	
218	        // Multiple distinct candidates. Classify:
219	        //   (a) all the SAME target but distinct cfg conds → cfg-exclusive worlds
220	        //       (or distinct conditioned definitions) → ResolvedSet (never merged).
221	        //   (b) distinct targets that are pairwise cfg-EXCLUSIVE → ResolvedSet
222	        //       (the cfg-duplicate-mod / cfg-impl case — distinct worlds).
223	        //   (c) distinct targets under COMPATIBLE cfg → Ambiguous (a genuine
224	        //       conflict; the consumer falls through, never a silent pick).
225	        let all_cfg_exclusive = pairwise_all_exclusive(&deduped);
226	        let same_target = deduped.iter().all(|c| c.target == deduped[0].target);
227	
228	        if same_target || all_cfg_exclusive {
229	            Resolution {
230	                candidates: deduped,
231	                status: ResStatus::ResolvedSet,
232	            }
233	        } else {
234	            Resolution {
235	                candidates: deduped,
236	                status: ResStatus::Ambiguous,
237	            }
238	        }
239	    }
240	
241	    fn visible(&self, binding: &Binding, q: &ResolveQuery, _trav: &TraversalCtx) -> bool {
242	        self.vis_reaches(&binding.vis, binding.scope, q.from)
243	            .unwrap_or(false)
244	    }
245	
246	    fn glob_edge_visible(
247	        &self,
248	        edge: &Edge,
249	        q: &ResolveQuery,
250	        _trav: &TraversalCtx,
251	    ) -> GlobEdgeVis {
252	        match self.vis_reaches(&edge.vis, edge.from, q.from) {
253	            Some(true) => GlobEdgeVis::Visible,
254	            Some(false) => GlobEdgeVis::Hidden,
255	            None => GlobEdgeVis::Unknown,
256	        }
257	    }
258	
259	    fn anchor(&self, anchor: &Anchor, from: ScopeId) -> Option<(ScopeId, NamespaceId)> {
260	        match anchor.kind {
261	            AnchorKind::CrateRoot => self.crate_root(from).map(|s| (s, NS_TYPE)),
262	            AnchorKind::SelfMod => self.enclosing_module(from).map(|s| (s, NS_TYPE)),
263	            AnchorKind::Super(n) => self.super_n(from, n).map(|s| (s, NS_TYPE)),
264	            AnchorKind::UsePath => {
265	                // A bare leading ident in a `use` path. 2015: crate-root-relative.
266	                // 2018+: lexical/extern-prelude — Phase 1 anchors at the enclosing
267	                // module (the lexical module), which is the recall-safe start (an
268	                // extern-prelude ident that is NOT an in-repo item falls through).
269	                if self.is_2018_plus() {
270	                    self.enclosing_module(from).map(|s| (s, NS_TYPE))
271	                } else {
272	                    self.crate_root(from).map(|s| (s, NS_TYPE))
273	                }
274	            }
275	            AnchorKind::LeadingColon => {
276	                // `::x`. 2018+: extern-prelude-based. 2015: crate-root-based.
277	                if self.is_2018_plus() {
278	                    // The populator records the prelude scope; without it we fall
279	                    // through (anchor conservatively over a wrong guess).
280	                    anchor.prelude.map(|s| (s, NS_TYPE))
281	                } else {
282	                    self.crate_root(from).map(|s| (s, NS_TYPE))
283	                }
284	            }
285	            AnchorKind::Bare => {
286	                // A bare expression-position leading ident. In Phase 1 these are
287	                // handled by `resolve` (the lexical walk), not `resolve_path`; if
288	                // an anchored Bare reaches here, start at the enclosing module
289	                // (recall-safe — never a wrong cross-module guess).
290	                self.enclosing_module(from).map(|s| (s, NS_TYPE))
291	            }
292	        }
293	    }
294	
295	    fn extern_crate_root(
296	        &self,
297	        graph: &ScopeGraph,
298	        name: &str,
299	        anchor: &Anchor,
300	        from: ScopeId,
301	    ) -> Option<ScopeId> {
302	        // Eligibility: only a 2018+ extern-prelude ROOT may name a sibling crate.
303	        // `crate::`/`self::`/`super::` anchor inside THIS crate; `LeadingColon`
304	        // (`::other::X`) is excluded in v1 (spec §8); a 2015 `use sibling::X` needs
305	        // an `extern crate` binding (modeled at walk/items.rs:160), so the bare
306	        // fallback must not invent one.
307	        if !self.is_2018_plus() {
308	            return None;
309	        }
310	        if !matches!(anchor.kind, AnchorKind::UsePath | AnchorKind::Bare) {
311	            return None;
312	        }
313	        // P3 (per-crate dep gate): resolve `name` ONLY through the consuming crate's
314	        // in-repo dependency map. A crate can name another in-repo crate iff it
315	        // actually depends on it; each map value is one specific target root.
316	        let consuming_root = crate_root_of(graph, from)?;
317	        graph
318	            .crate_deps_by_root
319	            .get(&consuming_root)?
320	            .get(&normalize_crate_ident(name))
321	            .copied()
322	    }
323	}
324	
325	/// True iff every pair of candidates is provably cfg-exclusive (distinct worlds).
326	fn pairwise_all_exclusive(cands: &[Candidate]) -> bool {
327	    if cands.len() < 2 {
328	        return false;
329	    }
330	    for i in 0..cands.len() {
331	        for j in (i + 1)..cands.len() {
332	            if !cands[i].cond.exclusive(&cands[j].cond) {
333	                return false;
334	            }
335	        }
336	    }
337	    true
338	}
339	
340	/// Normalize a crate/dependency identifier to the Rust path-identifier form: a
341	/// Cargo dependency name may carry hyphens (`my-crate`) while a `use` path writes
342	/// underscores (`my_crate`). Used to key `ScopeGraph::crate_deps_by_root` and to
343	/// normalize the leading-segment query in `extern_crate_root` identically.
344	pub(crate) fn normalize_crate_ident(name: &str) -> String {
345	    name.replace('-', "_")
346	}
347	
348	/// Climb `graph.scope(id).parent` from `from` to its enclosing `Root` scope and
349	/// return it. A free helper (the trait hook receives `graph` as a parameter, not
350	/// `RustPolicy`'s borrowed graph). Returns `None` only for a malformed graph with
351	/// no Root ancestor.
352	pub(crate) fn crate_root_of(graph: &ScopeGraph, from: ScopeId) -> Option<ScopeId> {
353	    let mut cur = Some(from);
354	    while let Some(id) = cur {
355	        let s = graph.scope(id)?;
356	        if matches!(s.kind, ScopeKind::Root) {
357	            return Some(id);
358	        }
359	        cur = s.parent;
360	    }
361	    None
362	}
