//! The Rust [`ResolutionPolicy`] (Task 2, PR-1).
//!
//! Every Rust-specific resolution rule lives here — the engine
//! ([`crate::name_resolution::engine`]) is language-neutral and consults this
//! policy at each decision point. This struct supplies:
//!
//! - **Namespaces** `{Type, Value, Macro}` (Type is scope-bearing for prefixes).
//! - **Per-rib edge order** — Rust follows only `Glob` edges at a rib (the
//!   lexical-parent step is the engine's structural ascent, gated by
//!   `ascend_to_parent`); explicit binding ▷ this-scope glob ▷ lexical parent.
//! - **MODULE-BOUNDARY STOP** for bare names (`ascend_to_parent`): a bare name
//!   crosses `Block`/`Callable`/`Type` parents but **stops at the enclosing
//!   `Module`/`Root`** — Rust does not inherit unqualified names across a module
//!   boundary (§4 round6-B1). Only explicit `super::`/`crate::`/`self::` anchors
//!   + the extern-prelude reach module ancestors.
//! - **`visible()`** — `pub` / `pub(crate)` / `pub(super)` / `pub(in path)` /
//!   private accessibility, computed against the borrowed [`ScopeGraph`]'s
//!   ancestry. Un-enforced / unknown visibility **falls through** (never
//!   resolves a not-visible target — §7).
//! - **`combine()`** — single ⇒ `Resolved`; same-target dedup ⇒ `Resolved`;
//!   distinct-namespace set ⇒ `ResolvedSet`; cfg-exclusive worlds ⇒
//!   `ResolvedSet` (distinct worlds, never merged); conflicting compatible-cfg
//!   ⇒ `Ambiguous`.
//! - **Edition-aware anchors** (`crate`/`self`/`super`/bare/`::`, 2015 vs 2018).
//!
//! ## Recall-safety stance
//! Every hook is written so the *worst* outcome is a missed edge, never a wrong
//! one: an unknown visibility kind is **not visible**, an un-mappable anchor is
//! `None` (fall through), a non-provably-exclusive conflict is `Ambiguous`.

use crate::name_resolution::graph::ScopeGraph;
use crate::name_resolution::types::{
    Anchor, AnchorKind, Binding, Candidate, Edge, EdgeKindId, GlobEdgeVis, NamespaceId, ResStatus,
    Resolution, ResolutionPolicy, ResolveQuery, ScopeId, ScopeKind, TraversalCtx, Vis, VisKindId,
};

// ── Rust namespace registry (policy-owned discriminants) ──────────────────────

/// Type namespace (modules, structs, enums, traits, type aliases).
pub const NS_TYPE: NamespaceId = 0;
/// Value namespace (fns, consts, statics, locals, tuple/unit ctors).
pub const NS_VALUE: NamespaceId = 1;
/// Macro namespace.
pub const NS_MACRO: NamespaceId = 2;

// ── Rust visibility-kind registry ─────────────────────────────────────────────

/// `pub` — visible everywhere the path reaches.
pub const VIS_PUB: VisKindId = 0;
/// `pub(crate)` — visible anywhere in the defining crate.
pub const VIS_PUB_CRATE: VisKindId = 1;
/// `pub(super)` — visible in the parent module's subtree.
pub const VIS_PUB_SUPER: VisKindId = 2;
/// `pub(in path)` — visible only inside the `restrict` scope's subtree.
pub const VIS_PUB_IN: VisKindId = 3;
/// private (the default) — visible in the defining module and its descendants.
pub const VIS_PRIV: VisKindId = 4;

// ── Rust edge-kind registry ───────────────────────────────────────────────────

/// A `use a::*` / `pub use a::*` glob edge.
pub const EK_GLOB: EdgeKindId = 1;

// ── The policy struct ─────────────────────────────────────────────────────────

/// The Rust resolution policy.
///
/// Borrows the [`ScopeGraph`] so `visible()` can compute module ancestry for
/// `pub(super)`/`pub(in)`/`pub(crate)`. `edition` selects 2015 vs 2018+ anchor
/// semantics (the only edition split Phase 1 needs).
pub struct RustPolicy<'g> {
    graph: &'g ScopeGraph,
    edition: u16,
}

impl<'g> RustPolicy<'g> {
    /// Construct a policy over `graph` for the given `edition` (e.g. 2015/2018).
    pub fn new(graph: &'g ScopeGraph, edition: u16) -> Self {
        RustPolicy { graph, edition }
    }

    fn is_2018_plus(&self) -> bool {
        self.edition >= 2018
    }

    /// The enclosing `Module`/`Root` of `scope` (itself if it is one).
    fn enclosing_module(&self, scope: ScopeId) -> Option<ScopeId> {
        let mut cur = Some(scope);
        while let Some(id) = cur {
            let s = self.graph.scope(id)?;
            if matches!(s.kind, ScopeKind::Module | ScopeKind::Root) {
                return Some(id);
            }
            cur = s.parent;
        }
        None
    }

    /// The crate `Root` ancestor of `scope`.
    ///
    /// Walks the parent chain and returns on the **first** (nearest) `Root` found;
    /// the `break` exits immediately, so the variable holds that Root, not a "last"
    /// or topmost one.
    fn crate_root(&self, scope: ScopeId) -> Option<ScopeId> {
        let mut cur = Some(scope);
        let mut root = None;
        while let Some(id) = cur {
            let s = self.graph.scope(id)?;
            if matches!(s.kind, ScopeKind::Root) {
                root = Some(id);
                break; // first Root found — exit immediately
            }
            cur = s.parent;
            if cur.is_none() {
                // Graph-without-Root safety net: no Root ancestor exists; treat
                // the topmost reachable scope as the crate root.
                root = Some(id);
            }
        }
        root
    }

    /// Walk `n` module hops up from `scope`'s enclosing module.
    fn super_n(&self, scope: ScopeId, n: u32) -> Option<ScopeId> {
        let mut cur = self.enclosing_module(scope)?;
        for _ in 0..n {
            // `super` of the crate Root is undefined → fall through.
            let parent = self.graph.parent_of(cur)?;
            cur = self.enclosing_module(parent)?;
        }
        Some(cur)
    }

    /// Is `desc` inside `ancestor`'s subtree (inclusive)?
    fn is_within(&self, desc: ScopeId, ancestor: ScopeId) -> bool {
        let mut cur = Some(desc);
        while let Some(id) = cur {
            if id == ancestor {
                return true;
            }
            cur = self.graph.parent_of(id);
        }
        false
    }

    fn vis_reaches(&self, vis: &Vis, def_scope: ScopeId, from: ScopeId) -> Option<bool> {
        let def_module = match self.enclosing_module(def_scope) {
            Some(m) => m,
            None => return Some(false),
        };
        match vis.kind {
            VIS_PUB => Some(true),
            VIS_PUB_CRATE => Some(match (self.crate_root(def_scope), self.crate_root(from)) {
                (Some(a), Some(b)) => a == b,
                _ => false,
            }),
            VIS_PUB_SUPER => Some(match self.super_n(def_scope, 1) {
                Some(parent_mod) => self.is_within(from, parent_mod),
                None => false,
            }),
            VIS_PUB_IN => vis.restrict.map(|r| self.is_within(from, r)),
            VIS_PRIV => Some(self.is_within(from, def_module)),
            _ => Some(false),
        }
    }
}

impl ResolutionPolicy for RustPolicy<'_> {
    fn namespaces(&self) -> Vec<NamespaceId> {
        // Scope-bearing namespaces for resolve_path prefixes: Type (modules,
        // type bodies). Value/Macro are final-segment-only.
        vec![NS_TYPE]
    }

    fn edge_order(&self) -> Vec<EdgeKindId> {
        // Rust follows only Glob edges at a rib. (Lexical parent ascent is the
        // engine's structural step, gated by `ascend_to_parent` below.)
        vec![EK_GLOB]
    }

    fn ascend_to_parent(&self, kind: &ScopeKind) -> bool {
        // THE MODULE-BOUNDARY STOP. A bare name crosses block/callable/type
        // lexical parents, but once we have looked in a Module/Root we STOP —
        // Rust does not inherit unqualified names from a parent module.
        matches!(
            kind,
            ScopeKind::Block | ScopeKind::Callable | ScopeKind::Type
        )
    }

    fn combine(&self, candidates: Vec<Candidate>) -> Resolution {
        if candidates.is_empty() {
            return Resolution {
                candidates,
                status: ResStatus::Unresolved,
            };
        }
        // Dedup exact-duplicate candidates (same target + same cond) — e.g. two
        // glob paths to the SAME item (a re-export diamond) is a single Resolved,
        // not Ambiguous.
        let mut deduped: Vec<Candidate> = Vec::new();
        for c in candidates {
            if !deduped
                .iter()
                .any(|d| d.target == c.target && d.cond == c.cond)
            {
                deduped.push(c);
            }
        }

        if deduped.len() == 1 {
            return Resolution {
                candidates: deduped,
                status: ResStatus::Resolved,
            };
        }

        // Multiple distinct candidates. Classify:
        //   (a) all the SAME target but distinct cfg conds → cfg-exclusive worlds
        //       (or distinct conditioned definitions) → ResolvedSet (never merged).
        //   (b) distinct targets that are pairwise cfg-EXCLUSIVE → ResolvedSet
        //       (the cfg-duplicate-mod / cfg-impl case — distinct worlds).
        //   (c) distinct targets under COMPATIBLE cfg → Ambiguous (a genuine
        //       conflict; the consumer falls through, never a silent pick).
        let all_cfg_exclusive = pairwise_all_exclusive(&deduped);
        let same_target = deduped.iter().all(|c| c.target == deduped[0].target);

        if same_target || all_cfg_exclusive {
            Resolution {
                candidates: deduped,
                status: ResStatus::ResolvedSet,
            }
        } else {
            Resolution {
                candidates: deduped,
                status: ResStatus::Ambiguous,
            }
        }
    }

    fn visible(&self, binding: &Binding, q: &ResolveQuery, _trav: &TraversalCtx) -> bool {
        self.vis_reaches(&binding.vis, binding.scope, q.from)
            .unwrap_or(false)
    }

    fn glob_edge_visible(
        &self,
        edge: &Edge,
        q: &ResolveQuery,
        _trav: &TraversalCtx,
    ) -> GlobEdgeVis {
        match self.vis_reaches(&edge.vis, edge.from, q.from) {
            Some(true) => GlobEdgeVis::Visible,
            Some(false) => GlobEdgeVis::Hidden,
            None => GlobEdgeVis::Unknown,
        }
    }

    fn anchor(&self, anchor: &Anchor, from: ScopeId) -> Option<(ScopeId, NamespaceId)> {
        match anchor.kind {
            AnchorKind::CrateRoot => self.crate_root(from).map(|s| (s, NS_TYPE)),
            AnchorKind::SelfMod => self.enclosing_module(from).map(|s| (s, NS_TYPE)),
            AnchorKind::Super(n) => self.super_n(from, n).map(|s| (s, NS_TYPE)),
            AnchorKind::UsePath => {
                // A bare leading ident in a `use` path. 2015: crate-root-relative.
                // 2018+: lexical/extern-prelude — Phase 1 anchors at the enclosing
                // module (the lexical module), which is the recall-safe start (an
                // extern-prelude ident that is NOT an in-repo item falls through).
                if self.is_2018_plus() {
                    self.enclosing_module(from).map(|s| (s, NS_TYPE))
                } else {
                    self.crate_root(from).map(|s| (s, NS_TYPE))
                }
            }
            AnchorKind::LeadingColon => {
                // `::x`. 2018+: extern-prelude-based. 2015: crate-root-based.
                if self.is_2018_plus() {
                    // The populator records the prelude scope; without it we fall
                    // through (anchor conservatively over a wrong guess).
                    anchor.prelude.map(|s| (s, NS_TYPE))
                } else {
                    self.crate_root(from).map(|s| (s, NS_TYPE))
                }
            }
            AnchorKind::Bare => {
                // A bare expression-position leading ident. In Phase 1 these are
                // handled by `resolve` (the lexical walk), not `resolve_path`; if
                // an anchored Bare reaches here, start at the enclosing module
                // (recall-safe — never a wrong cross-module guess).
                self.enclosing_module(from).map(|s| (s, NS_TYPE))
            }
        }
    }

    fn extern_crate_root(
        &self,
        graph: &ScopeGraph,
        name: &str,
        anchor: &Anchor,
        from: ScopeId,
    ) -> Option<ScopeId> {
        // Eligibility: only a 2018+ extern-prelude ROOT may name a sibling crate.
        // `crate::`/`self::`/`super::` anchor inside THIS crate; `LeadingColon`
        // (`::other::X`) is excluded in v1 (spec §8); a 2015 `use sibling::X` needs
        // an `extern crate` binding (modeled at walk/items.rs:160), so the bare
        // fallback must not invent one.
        if !self.is_2018_plus() {
            return None;
        }
        if !matches!(anchor.kind, AnchorKind::UsePath | AnchorKind::Bare) {
            return None;
        }
        // P3 (per-crate dep gate): resolve `name` ONLY through the consuming crate's
        // in-repo dependency map. A crate can name another in-repo crate iff it
        // actually depends on it; each map value is one specific target root.
        let consuming_root = crate_root_of(graph, from)?;
        graph
            .crate_deps_by_root
            .get(&consuming_root)?
            .get(&normalize_crate_ident(name))
            .copied()
    }
}

/// True iff every pair of candidates is provably cfg-exclusive (distinct worlds).
fn pairwise_all_exclusive(cands: &[Candidate]) -> bool {
    if cands.len() < 2 {
        return false;
    }
    for i in 0..cands.len() {
        for j in (i + 1)..cands.len() {
            if !cands[i].cond.exclusive(&cands[j].cond) {
                return false;
            }
        }
    }
    true
}

/// Normalize a crate/dependency identifier to the Rust path-identifier form: a
/// Cargo dependency name may carry hyphens (`my-crate`) while a `use` path writes
/// underscores (`my_crate`). Used to key `ScopeGraph::crate_deps_by_root` and to
/// normalize the leading-segment query in `extern_crate_root` identically.
pub(crate) fn normalize_crate_ident(name: &str) -> String {
    name.replace('-', "_")
}

/// Climb `graph.scope(id).parent` from `from` to its enclosing `Root` scope and
/// return it. A free helper (the trait hook receives `graph` as a parameter, not
/// `RustPolicy`'s borrowed graph). Returns `None` only for a malformed graph with
/// no Root ancestor.
pub(crate) fn crate_root_of(graph: &ScopeGraph, from: ScopeId) -> Option<ScopeId> {
    let mut cur = Some(from);
    while let Some(id) = cur {
        let s = graph.scope(id)?;
        if matches!(s.kind, ScopeKind::Root) {
            return Some(id);
        }
        cur = s.parent;
    }
    None
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::name_resolution::graph::ScopeGraph;
    use crate::name_resolution::types::{
        Anchor, ResolutionPolicy, Scope, ScopeExtent, ScopeId, ScopeKind, SourceLoc, Span,
    };

    fn root_scope(id: u32) -> Scope {
        Scope {
            id: ScopeId(id),
            kind: ScopeKind::Root,
            parent: None,
            extents: vec![ScopeExtent {
                file: crate::name_resolution::types::FileId(id),
                range: Span {
                    lo: SourceLoc {
                        file: crate::name_resolution::types::FileId(id),
                        byte: 0,
                    },
                    hi: SourceLoc {
                        file: crate::name_resolution::types::FileId(id),
                        byte: 10,
                    },
                },
                cond: None,
                occ: None,
            }],
            owner_item: None,
            cond: None,
        }
    }

    fn module_under(id: u32, parent: u32) -> Scope {
        let mut s = root_scope(id);
        s.kind = ScopeKind::Module;
        s.parent = Some(ScopeId(parent));
        s
    }

    /// A graph: Root(0) [crate a] with module(2); Root(1) [crate b]. a depends on b.
    fn two_crate_graph() -> ScopeGraph {
        let mut g = ScopeGraph::new();
        g.edition = 2021;
        g.add_scope(root_scope(0));
        g.add_scope(root_scope(1));
        g.add_scope(module_under(2, 0));
        let mut a_deps = std::collections::BTreeMap::new();
        a_deps.insert("b_crate".to_string(), ScopeId(1));
        g.crate_deps_by_root.insert(ScopeId(0), a_deps);
        g
    }

    #[test]
    fn extern_crate_root_resolves_declared_dep_from_use_path() {
        let g = two_crate_graph();
        let policy = RustPolicy::new(&g, 2021);
        // From module(2) inside crate a, a UsePath leading `b_crate` -> b's Root(1).
        let got = policy.extern_crate_root(&g, "b_crate", &Anchor::use_path_2015(), ScopeId(2));
        assert_eq!(got, Some(ScopeId(1)));
    }

    #[test]
    fn extern_crate_root_declines_2015() {
        let g = two_crate_graph();
        let policy = RustPolicy::new(&g, 2015); // 2015: the bare fallback must not fire.
        assert_eq!(
            policy.extern_crate_root(&g, "b_crate", &Anchor::use_path_2015(), ScopeId(2)),
            None
        );
    }

    #[test]
    fn extern_crate_root_declines_crate_self_super_anchors() {
        let g = two_crate_graph();
        let policy = RustPolicy::new(&g, 2021);
        for anchor in [Anchor::crate_root(), Anchor::self_mod(), Anchor::super_n(1)] {
            assert_eq!(
                policy.extern_crate_root(&g, "b_crate", &anchor, ScopeId(2)),
                None,
                "crate::/self::/super:: anchor inside THIS crate, not a sibling"
            );
        }
    }

    #[test]
    fn extern_crate_root_declines_leading_colon() {
        let g = two_crate_graph();
        let policy = RustPolicy::new(&g, 2021);
        assert_eq!(
            policy.extern_crate_root(&g, "b_crate", &Anchor::leading_colon_2018(99), ScopeId(2)),
            None,
            "LeadingColon is excluded in v1 (spec §8)"
        );
    }

    #[test]
    fn extern_crate_root_declines_undeclared_name() {
        let g = two_crate_graph();
        let policy = RustPolicy::new(&g, 2021);
        // `other` is not in a's dep map → decline (per-crate dep gate, P3).
        assert_eq!(
            policy.extern_crate_root(&g, "other", &Anchor::use_path_2015(), ScopeId(2)),
            None
        );
    }

    #[test]
    fn extern_crate_root_is_per_consuming_crate() {
        let g = two_crate_graph();
        let policy = RustPolicy::new(&g, 2021);
        // From crate b's Root(1) there is no dep map entry → `b_crate` declines.
        assert_eq!(
            policy.extern_crate_root(&g, "b_crate", &Anchor::use_path_2015(), ScopeId(1)),
            None,
            "the extern prelude is per-crate; b does not declare b_crate"
        );
    }

    #[test]
    fn extern_crate_root_normalizes_hyphen() {
        let mut g = two_crate_graph();
        // a depends on a hyphenated in-repo crate keyed underscore in the map.
        g.crate_deps_by_root
            .get_mut(&ScopeId(0))
            .unwrap()
            .insert("my_dep".to_string(), ScopeId(1));
        let policy = RustPolicy::new(&g, 2021);
        // A `use my-dep::X` writes `my_dep`; either spelling normalizes to the key.
        assert_eq!(
            policy.extern_crate_root(&g, "my-dep", &Anchor::use_path_2015(), ScopeId(2)),
            Some(ScopeId(1))
        );
    }

    #[test]
    fn crate_root_of_climbs_to_root() {
        let g = two_crate_graph();
        assert_eq!(crate_root_of(&g, ScopeId(2)), Some(ScopeId(0)));
        assert_eq!(crate_root_of(&g, ScopeId(0)), Some(ScopeId(0)));
    }
}

#[cfg(test)]
mod vis_reaches_tests {
    use super::*;
    use crate::name_resolution::graph::ScopeGraph;
    use crate::name_resolution::types::{
        BindTarget, Binding, FileId, ItemId, PolicyBlob, PolicyQueryCtx, ResolveQuery, Scope,
        ScopeExtent, SourceLoc, Span, Target, Vis,
    };

    fn loc(byte: usize) -> SourceLoc {
        SourceLoc {
            file: FileId(0),
            byte,
        }
    }

    fn scope(id: u32, kind: ScopeKind, parent: Option<u32>) -> Scope {
        Scope {
            id: ScopeId(id),
            kind,
            parent: parent.map(ScopeId),
            extents: vec![ScopeExtent {
                file: FileId(0),
                range: Span {
                    lo: loc(0),
                    hi: loc(100),
                },
                cond: None,
                occ: None,
            }],
            owner_item: None,
            cond: None,
        }
    }

    fn vis(kind: VisKindId, restrict: Option<ScopeId>) -> Vis {
        Vis {
            kind,
            restrict,
            payload: PolicyBlob::default(),
        }
    }

    fn binding(scope: ScopeId, name: &str, vis: Vis) -> Binding {
        Binding {
            scope,
            name: name.to_string(),
            ns: NS_TYPE,
            target: BindTarget::Resolved(Target::Item {
                id: ItemId(1),
                ns: NS_TYPE,
                owns: None,
                callable: false,
            }),
            vis,
            cond: None,
            vis_extents: vec![],
        }
    }

    fn query(from: ScopeId) -> ResolveQuery {
        ResolveQuery {
            name: "P".to_string(),
            ns: NS_TYPE,
            from,
            at: loc(1),
            cfg: Default::default(),
            ctx: PolicyQueryCtx::default(),
        }
    }

    #[test]
    fn vis_reaches_matches_visible_and_preserves_unknown_pub_in() {
        let mut graph = ScopeGraph::new();
        graph.add_scope(scope(0, ScopeKind::Root, None));
        graph.add_scope(scope(1, ScopeKind::Module, Some(0)));
        let policy = RustPolicy::new(&graph, 2021);

        let pub_vis = vis(VIS_PUB, None);
        let priv_vis = vis(VIS_PRIV, None);
        let unknown_pub_in = vis(VIS_PUB_IN, None);

        assert_eq!(
            policy.vis_reaches(&pub_vis, ScopeId(1), ScopeId(0)),
            Some(true)
        );
        let pub_binding = binding(ScopeId(1), "P", pub_vis);
        assert_eq!(
            policy.visible(&pub_binding, &query(ScopeId(0)), &TraversalCtx::default()),
            policy
                .vis_reaches(&pub_binding.vis, pub_binding.scope, ScopeId(0))
                .unwrap_or(false)
        );

        assert_eq!(
            policy.vis_reaches(&priv_vis, ScopeId(1), ScopeId(0)),
            Some(false)
        );
        assert_eq!(
            policy.vis_reaches(&priv_vis, ScopeId(1), ScopeId(1)),
            Some(true)
        );
        let priv_binding = binding(ScopeId(1), "H", priv_vis);
        assert_eq!(
            policy.visible(&priv_binding, &query(ScopeId(0)), &TraversalCtx::default()),
            policy
                .vis_reaches(&priv_binding.vis, priv_binding.scope, ScopeId(0))
                .unwrap_or(false)
        );

        assert_eq!(
            policy.vis_reaches(&unknown_pub_in, ScopeId(1), ScopeId(0)),
            None
        );
    }
}

//! Scope-graph core data model — Task 1 (PR-1).
//!
//! Transcribed faithfully from the design-of-record spec §1
//! (`docs/superpowers/specs/2026-06-17-prism-rust-module-resolution-design.md`).
//!
//! **No engine / no behavior.** This module defines *only* the leaf data-model
//! types and the `ResolutionPolicy` trait signature. The graph *container*
//! (`ScopeGraph` + `MacroWildcard`) lives in [`crate::name_resolution::graph`];
//! engine logic in [`crate::name_resolution::engine`]; population in PR-2.
//!
//! ## Determinism
//! All multi-item collections use `BTreeMap`/`BTreeSet`; all key types derive
//! `Ord`/`PartialOrd`. `Vec` fields whose order is meaningful keep insertion
//! order (extent/candidate lists) — callers must insert in a stable order.
//!
//! ## Serialization stability
//! All public types derive `Serialize` + `Deserialize`. Field names are the
//! canonical names from the spec; do not rename without a spec revision.

use serde::{Deserialize, Serialize};

use crate::name_resolution::graph::ScopeGraph;

// ── Opaque IDs ──────────────────────────────────────────────────────────────

/// Identifies a scope in the scope graph.
///
/// Stable-ID derivation (from content) is Task 3; for now these are
/// assigned by the populator.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash, Serialize, Deserialize)]
pub struct ScopeId(pub u32);

/// Identifies a defining item in the repo.
///
/// Stable-ID derivation is Task 3.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash, Serialize, Deserialize)]
pub struct ItemId(pub u32);

/// Identifies a source file.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash, Serialize, Deserialize)]
pub struct FileId(pub u32);

/// Identifies a compilation unit (e.g., a C++ TU). Reserved for Phase 3.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash, Serialize, Deserialize)]
pub struct UnitId(pub u32);

// ── Open type aliases — policy-owned ────────────────────────────────────────

/// Namespace discriminant.  Policy-owned.
/// Rust: Type=0 / Value=1 / Macro=2 (conventional; policy owns the registry).
pub type NamespaceId = u16;

/// Visibility kind discriminant.  Policy-owned (policy owns the registry).
/// Rust: pub=0 / pub(crate)=1 / pub(super)=2 / pub(in)=3 / priv=4 (conventional).
pub type VisKindId = u16;

/// Edge kind discriminant.  Policy-owned (lexical ascent is structural, not an edge).
/// Rust: Glob=1 (conventional; policy owns the registry).
pub type EdgeKindId = u16;

// ── Source locations ─────────────────────────────────────────────────────────

/// A byte-offset location inside a specific file.
#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord, Hash, Serialize, Deserialize)]
pub struct SourceLoc {
    pub file: FileId,
    pub byte: usize,
}

/// A half-open byte range `[lo, hi)` within (in practice) the same file.
#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord, Hash, Serialize, Deserialize)]
pub struct Span {
    pub lo: SourceLoc,
    pub hi: SourceLoc,
}

// ── CfgCond — configuration-condition formula ────────────────────────────────

/// A cfg-condition formula (rev-3/M10).
///
/// `compatible(other)` and `exclusive(other)` are the two query methods;
/// the engine uses them to decide whether two conditioned candidates can
/// coexist or are mutually exclusive.
///
/// ## Conservative-on-unknown rule
/// When the formula is complex or involves atoms the engine cannot evaluate,
/// both methods fall back to the conservative answer:
/// - `compatible` → `true` (assume they may coexist → no silent merge)
/// - `exclusive`  → `false` (assume they might coexist → no silent drop)
#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord, Hash, Serialize, Deserialize)]
pub enum CfgCond {
    /// Unconditionally active.
    True,
    /// `cfg(key)` or `cfg(key = "val")`.
    Atom(String, Option<String>),
    /// `not(inner)`.
    Not(Box<CfgCond>),
    /// `all(…)`.
    And(Vec<CfgCond>),
    /// `any(…)`.
    Or(Vec<CfgCond>),
}

impl CfgCond {
    /// Returns `true` when `self` and `other` *might* be simultaneously
    /// active — i.e., they are **not provably exclusive**.
    ///
    /// Conservative: unknown combinations return `true`.
    pub fn compatible(&self, other: &CfgCond) -> bool {
        !self.exclusive(other)
    }

    /// Returns `true` when `self` and `other` **cannot** be simultaneously
    /// active.
    ///
    /// Conservative: only the cases we can prove exclusive return `true`;
    /// everything else returns `false` (safe — may miss some exclusive pairs).
    pub fn exclusive(&self, other: &CfgCond) -> bool {
        match (self, other) {
            // not(x) is exclusive with x
            (CfgCond::Not(inner), _) if inner.as_ref() == other => true,
            (_, CfgCond::Not(inner)) if inner.as_ref() == self => true,

            // Two atoms with the same key but different *Some* values are exclusive
            // (e.g. target_os="linux" vs target_os="windows").
            // Atom(key, None) vs Atom(key, Some(_)): unknown — conservative false.
            // Phase 2 (before cfg EVALUATION): exclude additive keys (feature, target_feature) — they compose, so feature="a" vs feature="b" are NOT exclusive. Safe in Phase 1 (multi-candidate falls through either way).
            (CfgCond::Atom(k1, Some(v1)), CfgCond::Atom(k2, Some(v2))) => k1 == k2 && v1 != v2,

            _ => false,
        }
    }
}

// ── Occurrence (RESERVED — C++ Phase 3) ─────────────────────────────────────

/// A declaration occurrence, scoped to a compilation unit.
///
/// **RESERVED** (rev-5/round5-B4): C++ include-occurrence visibility. A
/// declaration is visible in a TU only after its include point. Population
/// and enforcement are deferred to Phase 3 (C++ populator).
#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord, Hash, Serialize, Deserialize)]
pub struct Occurrence {
    pub unit: Option<UnitId>,
    /// Ordinal within the unit (include/expansion order).
    pub order: u32,
}

// ── ScopeExtent ──────────────────────────────────────────────────────────────

/// The source extent of one "opening" of a scope.
///
/// A scope may have multiple extents (C++ reopened namespaces, macro-merged
/// TS declaration namespaces).
///
/// `occ` is **RESERVED** for C++ Phase 3.
#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord, Hash, Serialize, Deserialize)]
pub struct ScopeExtent {
    pub file: FileId,
    pub range: Span,
    pub cond: Option<CfgCond>,
    /// RESERVED — C++ occurrence-visibility (Phase 3).
    pub occ: Option<Occurrence>,
}

// ── ScopeKind ────────────────────────────────────────────────────────────────

/// The kind of a scope node.
#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord, Hash, Serialize, Deserialize)]
pub enum ScopeKind {
    /// Crate root.
    Root,
    /// A `mod foo` or package-level scope.
    Module,
    /// A block `{}` inside a function or other item.
    Block,
    /// A `struct`/`enum`/`trait`/`class` type scope.
    Type,
    /// A function or method body scope.
    Callable,
    /// The implicit extern-prelude scope (std/core/alloc + extern crates).
    ExternPrelude,
    /// A C++ translation unit (RESERVED — Phase 3).
    TranslationUnit,
}

// ── Scope ────────────────────────────────────────────────────────────────────

/// A binding region in the scope graph.
///
/// `parent` is the **lexical** enclosing scope. `extents` carries 1 or more
/// source ranges (a normal scope has exactly 1; reopened/multi-file scopes
/// accumulate more). `owner_item` links a scope to the item that owns it
/// (e.g. the `struct` that owns its field scope).
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct Scope {
    pub id: ScopeId,
    pub kind: ScopeKind,
    /// Lexical enclosing scope (`None` only for the crate Root).
    pub parent: Option<ScopeId>,
    /// One extent per "opening" of this scope.
    pub extents: Vec<ScopeExtent>,
    /// The item that owns this scope (if any).
    pub owner_item: Option<ItemId>,
    pub cond: Option<CfgCond>,
}

// ── Vis — open visibility ────────────────────────────────────────────────────

/// An open, policy-interpreted visibility annotation.
///
/// `kind` is a policy-assigned `VisKindId` (Rust: pub/pub(crate)/priv/…).
/// `restrict` is the scope to which visibility is restricted (for `pub(in p)`).
/// `payload` is policy-opaque extra data (reserved).
#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord, Hash, Serialize, Deserialize)]
pub struct Vis {
    pub kind: VisKindId,
    pub restrict: Option<ScopeId>,
    /// Policy-opaque payload.  Use `Default::default()` unless the policy needs it.
    pub payload: PolicyBlob,
}

/// Opaque per-policy payload stored inside `Vis` and `Anchor`.
///
/// Reserved — policies may stash serialisable per-binding data here.
/// The engine treats this as an opaque blob.
#[derive(Debug, Clone, Default, PartialEq, Eq, PartialOrd, Ord, Hash, Serialize, Deserialize)]
pub struct PolicyBlob {
    // Phase N: policies may add typed fields here behind a feature or a
    // discriminated union.  For now the blob is empty (the unit struct
    // compiles and serializes as `{}` in JSON).
}

// ── Anchor ───────────────────────────────────────────────────────────────────

/// A path anchor — *how* a path's leading segment is rooted before the walk.
///
/// **Policy-owned / engine-opaque.** The engine never matches on `AnchorKind`;
/// only a `ResolutionPolicy::anchor` implementation interprets it (exactly as
/// `NamespaceId`/`VisKindId`/`EdgeKindId` are policy-interpreted scalars that
/// nonetheless live here in the neutral data model). The variants below are the
/// forms the Rust policy needs (Task 2); other languages may ignore them or add
/// their own conventions via `Anchor::default()` + `payload`.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash, Serialize, Deserialize)]
pub enum AnchorKind {
    /// A bare leading ident in an **expression** position (edition-lexical).
    Bare,
    /// `self::` — module-relative to the enclosing `Module`.
    SelfMod,
    /// `super::` ×n — n hops up the module ancestry.
    Super(u32),
    /// `crate::` — the enclosing crate Root.
    CrateRoot,
    /// A bare leading ident inside a **`use` path** (edition-sensitive rooting:
    /// 2015 crate-root-relative; 2018+ lexical/extern-prelude).
    UsePath,
    /// A leading `::` — 2015 crate-root-based; 2018+ extern-prelude-based.
    LeadingColon,
}

/// Opaque per-policy anchor mapping for path resolution prefixes.
///
/// The populator maps `crate::` / `self::` / `super::` / `::` / bare idents to a
/// starting scope + rule via an `Anchor`.  Policy-owned; the engine passes it
/// verbatim to `ResolutionPolicy::anchor` and never inspects the fields.
///
/// `prelude` carries the extern-prelude `ScopeId` when the populator knows it
/// (2018 `::x`); `None` ⇒ the policy anchors conservatively (fall through over a
/// wrong guess — §4.4).
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash, Serialize, Deserialize)]
pub struct Anchor {
    pub kind: AnchorKind,
    /// Extern-prelude scope, when known (for 2018 `::`/bare-crate anchoring).
    pub prelude: Option<ScopeId>,
}

impl Default for Anchor {
    /// A bare expression-position anchor with no known prelude — the most
    /// conservative default (lexical walk; never a wrong cross-module guess).
    fn default() -> Self {
        Anchor {
            kind: AnchorKind::Bare,
            prelude: None,
        }
    }
}

impl Anchor {
    /// `crate::` — root of the enclosing crate.
    pub fn crate_root() -> Self {
        Anchor {
            kind: AnchorKind::CrateRoot,
            prelude: None,
        }
    }
    /// `self::` — the enclosing module.
    pub fn self_mod() -> Self {
        Anchor {
            kind: AnchorKind::SelfMod,
            prelude: None,
        }
    }
    /// `super::` ×n.
    pub fn super_n(n: u32) -> Self {
        Anchor {
            kind: AnchorKind::Super(n),
            prelude: None,
        }
    }
    /// A bare expression-position leading ident.
    pub fn bare() -> Self {
        Anchor::default()
    }
    /// A 2015 `use`-path leading ident (crate-root-relative).
    pub fn use_path_2015() -> Self {
        Anchor {
            kind: AnchorKind::UsePath,
            prelude: None,
        }
    }
    /// A 2018 leading `::` with a known extern-prelude scope.
    pub fn leading_colon_2018(prelude: u32) -> Self {
        Anchor {
            kind: AnchorKind::LeadingColon,
            prelude: Some(ScopeId(prelude)),
        }
    }
}

// ── BindTarget / Target ──────────────────────────────────────────────────────

/// A single identifier (name segment), e.g. `"HashMap"` or `"fmt"`.
pub type Ident = String;

/// A raw (unresolved) path, as a list of name segments.
#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord, Hash, Serialize, Deserialize)]
pub struct RawPath(pub Vec<Ident>);

/// An opaque reference to a local binding (for `Target::Local`).
///
/// Phase N: when the engine builds edges it records the source `Binding`
/// identity here.  For now a pair of (scope, ordinal) suffices.
#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord, Hash, Serialize, Deserialize)]
pub struct BindingRef {
    pub scope: ScopeId,
    /// Insertion-order ordinal of the binding within the scope (0-based).
    pub ordinal: u32,
}

/// An opaque reference to an external (out-of-repo) definition.
#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord, Hash, Serialize, Deserialize)]
pub struct ExternRef {
    /// The canonical external name (e.g. `std::collections::HashMap`).
    pub name: String,
}

/// What a `Binding`'s name resolves to.
#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord, Hash, Serialize, Deserialize)]
pub enum Target {
    /// The name introduces or re-exports a *scope* (a module, type body, …).
    Scope(ScopeId),
    /// The name refers to a defining item in the repo.
    ///
    /// - `owns`: the scope this item's body introduces (for `Enum::Variant`,
    ///   `Trait::Assoc`, etc.).
    /// - `callable`: `true` only for `fn`/`method`/closure items — the engine
    ///   mints a call edge **only** for `Item{callable:true}`.
    Item {
        id: ItemId,
        ns: NamespaceId,
        owns: Option<ScopeId>,
        callable: bool,
    },
    /// A local value binding (param / `let` / closure arg / pattern).
    ///
    /// (rev-6/round6-2): shadows free-fn items in `Value` lookup but is NOT
    /// itself a call target.  `callable` must never be assumed for `Local`.
    Local(BindingRef),
    /// An out-of-repo definition (stdlib, external crate, …).
    External(ExternRef),
}

/// The resolution state of a `Binding`'s target.
#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord, Hash, Serialize, Deserialize)]
pub enum BindTarget {
    /// Target already known (either from an item definition or after fixpoint).
    Resolved(Target),
    /// Target not yet resolved — a named import (`use a::b`) waiting for fixpoint.
    Pending(RawPath, Anchor),
}

// ── Binding ──────────────────────────────────────────────────────────────────

/// A definition **or** an import/re-export alias inside a scope.
///
/// `(scope, name, ns)` is the lookup key; multiple bindings with the same
/// key are legal (cfg-alternatives, overloads, genuinely ambiguous).
///
/// `vis_extents` carries the multi-region, file-qualified visibility spans
/// (block scope + "visible after def" semantics; a macro may yield disjoint
/// visible regions).
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct Binding {
    pub scope: ScopeId,
    pub name: Ident,
    pub ns: NamespaceId,
    pub target: BindTarget,
    pub vis: Vis,
    pub cond: Option<CfgCond>,
    /// Multi-region file-qualified visibility spans.
    pub vis_extents: Vec<Span>,
}

// ── Edge ─────────────────────────────────────────────────────────────────────

/// A scope-to-scope (or scope-to-target) edge.
///
/// Named imports/re-exports are `Binding`s, not edges (rev-3/M7).
/// Globs (`use a::*`) are `Edge`s with a glob `EdgeKindId`.
///
/// `vis_range` is **RESERVED** for C++ include-occurrence visibility (Phase 3).
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct Edge {
    pub from: ScopeId,
    pub kind: EdgeKindId,
    pub to: BindTarget,
    pub vis: Vis,
    pub cond: Option<CfgCond>,
    /// Source/declaration order (base-list position, import order).
    pub order: u32,
    /// RESERVED — C++ include-occurrence visibility (Phase 3).
    pub vis_range: Option<Span>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum GlobEdgeVis {
    Visible,
    Hidden,
    Unknown,
}

// ── Resolution results ───────────────────────────────────────────────────────

/// Why / where a candidate was found (opaque to the engine; policy-set).
///
/// Phase N: the Rust policy fills this in with a structured provenance record.
#[derive(Debug, Clone, Default, PartialEq, Eq, PartialOrd, Ord, Hash, Serialize, Deserialize)]
pub struct Provenance {
    // Phase N: structured provenance (scope chain, edge kinds taken, …).
}

/// One resolution candidate returned by the engine.
#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord, Hash, Serialize, Deserialize)]
pub struct Candidate {
    pub target: Target,
    /// The accumulated cfg condition along the path to this candidate.
    pub cond: CfgCond,
    pub provenance: Provenance,
}

/// The outcome status of a resolution query.
#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord, Hash, Serialize, Deserialize)]
pub enum ResStatus {
    /// Exactly one candidate — the engine may mint an edge.
    Resolved,
    /// A legitimate set (C++ overloads; same name in >1 namespace).
    ResolvedSet,
    /// ≥2 conflicting candidates under compatible cfg — consumer falls through.
    Ambiguous,
    /// A deferred/unexpanded glob or still-`Pending` import shadowed this name.
    Poisoned,
    /// No candidate found.
    Unresolved,
}

/// The result of resolving a `ResolveQuery`.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct Resolution {
    pub candidates: Vec<Candidate>,
    pub status: ResStatus,
}

// ── ResolveQuery ─────────────────────────────────────────────────────────────

/// Traversal context passed to `ResolutionPolicy::visible()`.
///
/// The engine populates this at each lookup point; policy implementations
/// inspect it. It carries the **lookup scope** the binding was found in and
/// whether it was reached **via a glob edge** (vs a direct rib binding) — what
/// the Rust glob-re-export / accessible-not-just-public rule needs (§4), and
/// what C++ access control will consult later.
///
/// The engine deliberately does **not** hard-code a span/`SourceLoc` visibility
/// check (that would be Rust-shaped — §1); all visibility decisions go through
/// `visible()`, which may consult these fields + the binding's own data.
#[derive(Debug, Clone, Default, PartialEq, Eq, Serialize, Deserialize)]
pub struct TraversalCtx {
    /// The scope currently being searched (the rib the binding lives in / the
    /// glob target scope when `via_glob`).
    pub lookup_scope: Option<ScopeId>,
    /// `true` when the binding was reached through a `Glob` edge rather than as
    /// a direct binding at the current rib.
    pub via_glob: bool,
    /// The edge kind taken to reach the binding (when `via_glob`).
    pub edge_kind: Option<EdgeKindId>,
}

/// Opaque policy-query context.
///
/// C++ ADL / two-phase lookup extensions add fields here without changing the
/// engine.  **RESERVED** (round6-4).
#[derive(Debug, Clone, Default, PartialEq, Eq, Serialize, Deserialize)]
pub struct PolicyQueryCtx {
    // Phase N: call syntax, arg-type candidates, template args, ADL classes, etc.
}

/// Opaque cfg evaluation context supplied by the caller.
#[derive(Debug, Clone, Default, PartialEq, Eq, Serialize, Deserialize)]
pub struct CfgCtx {
    // Phase N: active feature flags, target OS/arch, … needed to evaluate CfgCond.
}

/// A structured query passed to `resolve` / `resolve_path`.
///
/// Extensible — C++ ADL / two-phase lookup may add fields to `ctx` without
/// touching the engine signature.
///
/// `ctx` is **RESERVED** (round6-4).
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct ResolveQuery {
    pub name: Ident,
    pub ns: NamespaceId,
    pub from: ScopeId,
    pub at: SourceLoc,
    pub cfg: CfgCtx,
    /// RESERVED — opaque policy-query context (ADL, call syntax, …).
    pub ctx: PolicyQueryCtx,
}

// ── ResolutionPolicy trait ────────────────────────────────────────────────────

/// A pluggable, per-language resolution policy.
///
/// The engine is language-neutral; it walks the scope graph and calls these
/// hooks at each decision point.  The Rust policy (`RustPolicy`) is
/// implemented in Task 2.  C++ / Go / Java / Python / TS-JS policies are
/// later phases.
///
/// All method bodies below are **trait signatures only**; stub `todo!()` bodies
/// are provided where a default makes no sense.  No engine logic belongs here.
pub trait ResolutionPolicy {
    /// The set of namespace IDs this policy recognises as "scope-bearing"
    /// for `resolve_path` prefix resolution (e.g. Type+Module in Rust).
    fn namespaces(&self) -> Vec<NamespaceId>;

    /// The ordered list of `EdgeKindId`s the engine should follow at each rib,
    /// in priority order (earlier = higher priority, shadows later).
    fn edge_order(&self) -> Vec<EdgeKindId>;

    /// Combine a list of raw candidates (from a single rib) into a `Resolution`.
    ///
    /// The policy decides:
    /// - single item → `Resolved`
    /// - legitimate multi-item (C++ overload set, multi-namespace) → `ResolvedSet`
    /// - conflicting items under compatible cfg → `Ambiguous`
    fn combine(&self, candidates: Vec<Candidate>) -> Resolution;

    /// Decides whether `binding` is accessible from query `q` during a traversal
    /// described by `trav`.
    ///
    /// The `trav` context supplies the current edge kind, lookup scope chain,
    /// and provenance — needed for Rust glob re-export visibility and C++ access
    /// control (round6-4 + round7-2/3).
    ///
    /// The engine does **not** hard-code a span check; all visibility decisions
    /// go through this hook.
    fn visible(&self, binding: &Binding, q: &ResolveQuery, trav: &TraversalCtx) -> bool;

    /// Decides whether a glob edge itself is accessible from query `q`.
    ///
    /// Default policies keep historical behavior: all glob edges are visible.
    fn glob_edge_visible(
        &self,
        _edge: &Edge,
        _q: &ResolveQuery,
        _trav: &TraversalCtx,
    ) -> GlobEdgeVis {
        GlobEdgeVis::Visible
    }

    /// Map a path anchor (`crate::`, `self::`, `super::`, bare ident, `::`) to
    /// the starting `ScopeId` + initial `NamespaceId` for the walk.
    ///
    /// Edition-aware for Rust (2015 vs 2018+).
    fn anchor(&self, anchor: &Anchor, from: ScopeId) -> Option<(ScopeId, NamespaceId)>;

    /// During a **bare-name** inner→outer walk, after looking in a scope of the
    /// given `kind`, should the engine ascend to its lexical parent?
    ///
    /// This is the policy's lexical-ascent gate. The **Rust module-boundary
    /// stop** lives here: a bare name crosses `Block`/`Callable`/`Type` parents
    /// but **stops at the enclosing `Module`/`Root`** (Rust does not inherit
    /// unqualified names from a parent module — §4 round6-B1).
    ///
    /// Default: `true` (an unconditional lexical walk) — for policies (e.g.
    /// Python LEGB) that do walk module ancestors. Rust overrides this.
    fn ascend_to_parent(&self, _kind: &ScopeKind) -> bool {
        true
    }

    /// Inject additional candidates (C++ ADL, prelude, …) for a query.
    ///
    /// Default: no injection (returns empty).  Override for languages that need it.
    fn inject(&self, _q: &ResolveQuery) -> Vec<Candidate> {
        vec![]
    }

    /// A path's leading segment may name a depended-on in-repo crate (Rust 2018+
    /// extern-prelude root). Returns that crate's library `Root` iff the anchor is
    /// an extern-prelude root kind AND the CONSUMING crate (containing `from`)
    /// declares an in-repo dependency under `name`. `from` is needed because the
    /// extern prelude is per-crate. Default: not applicable (returns `None`).
    fn extern_crate_root(
        &self,
        _graph: &ScopeGraph,
        _name: &str,
        _anchor: &Anchor,
        _from: ScopeId,
    ) -> Option<ScopeId> {
        None
    }
}

